```java
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class FileManager {

    private static final MessageDigest MD5_DIGEST;

    static {
        try {
            MD5_DIGEST = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to initialize MD5 digest", e);
        }
    }

    /**
     * Caches the received thumbnail image.
     * @param fileInfo the information about the file
     * @param inputStream the input stream containing the thumbnail image data
     * @throws IOException if an I/O error occurs
     */
    public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
        if (fileInfo == null || inputStream == null) {
            return;
        }

        // Generate a unique key for the thumbnail image based on its file information and MD5 hash
        String key = generateThumbnailKey(fileInfo);

        // Check if the key already exists in the cache
        if (thumbnailCache.containsKey(key)) {
            return; // The thumbnail image is already cached, so we don't need to store it again
        }

        // Cache the thumbnail image data
        try {
            byte[] thumbnailData = inputStream.readAllBytes();
            thumbnailCache.put(key, thumbnailData);
        } catch (Exception e) {
            throw new IOException("Failed to cache thumbnail image", e);
        }
    }

    // A static cache to store the thumbnail images
    private static final HashMap<String, byte[]> thumbnailCache = new HashMap<>();

    /**
     * Generates a unique key for the thumbnail image based on its file information and MD5 hash.
     * @param fileInfo the information about the file
     * @return a unique key for the thumbnail image
     */
    private static String generateThumbnailKey(BaseFileInfo fileInfo) {
        try {
            MD5_DIGEST.update(fileInfo.getName().getBytes());
            MD5_DIGEST.update(String.valueOf(fileInfo.getSize()).getBytes());
            MD5_DIGEST.update(fileInfo.getType().getBytes());

            // Calculate the MD5 hash of the file information
            byte[] hash = MD5_DIGEST.digest();

            // Encode the hash as a Base64 string and return it as the key
            return Base64.getEncoder().encodeToString(hash);
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate thumbnail key", e);
        }
    }
}
```

